package com.projects.adnan.EmailProject.entity;import com.projects.adnan.EmailProject.entity.enums.Folder;import jakarta.persistence.*;import lombok.Getter;import lombok.NoArgsConstructor;import lombok.Setter;import java.time.LocalDateTime;import java.util.ArrayList;import java.util.List;@Entity@Table(name = "emails",        uniqueConstraints = @UniqueConstraint(columnNames = {"user_id", "message_id", "folder"}),        indexes = @Index(name = "idx_emails_user_folder", columnList = "user_id, folder"))@Getter@Setter@NoArgsConstructorpublic class EmailMessage {    @Id    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @ManyToOne(fetch = FetchType.LAZY, optional = false)    @JoinColumn(name = "user_id", nullable = false)    private User user;    /** RFC 5322 Message-ID header, used to avoid duplicates on POP3 fetch */    @Column(name = "message_id", nullable = false, length = 255)    private String messageId;    @Enumerated(EnumType.STRING)    @Column(nullable = false, length = 10)    private Folder folder;    @Column(nullable = false)    private String sender;    @Column(nullable = false, columnDefinition = "TEXT")    private String recipients;    @Column(length = 500)    private String subject;    /** AES-256-GCM encrypted body */    @Column(name = "body_enc", columnDefinition = "BLOB")    private byte[] bodyEnc;    @Column(columnDefinition = "BLOB", length = 12)    private byte[] iv;    @Column(name = "sent_at")    private LocalDateTime sentAt;    @Column(name = "received_at")    private LocalDateTime receivedAt;    @Column(name = "is_read", nullable = false)    private boolean read = false;    @OneToMany(mappedBy = "email", cascade = CascadeType.ALL, orphanRemoval = true)    private List<Attachment> attachments = new ArrayList<>();    public void addAttachment(Attachment a) {        a.setEmail(this);        attachments.add(a);    }}